head.script:
            scwin.onpageload = function() {

            };

            scwin.onpageunload = function() {

            };

            scwin.mapchart1_contextFormatter = function(name, code) {
                return name + "<br>준공 0건," + "<br>진행 0건," + "<br>예정 0건";
            };
            scwin.mapchart1_markerDefiner = function(name, code) {
                if (code % 2 == 1) {
                    return true;
                } else {
                    return false;
                }
            };
            scwin.mapchart1_markerClassDefiner = function(name, code) {
                if (code % 3 == 1) {
                    return "class1";
                } else {
                    return "class2";
                }
            };

			scwin.checkVal = function() {
				return document.getElementsByClassName('class2').length == 12;
			}		

			scwin.unitTest = function() {
				//init
				WebSquare.wUnit.start();
				WebSquare.wUnit.addCommand("pause", "500");
				WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
				WebSquare.wUnit.addCommand("pause", "400");

				//Run  and stop
				WebSquare.wUnit.run();
				WebSquare.wUnit.stop();
			}
			scwin.unitTest();
